// Level sections and B3 art V0.01. External Editor-only tool; no game behaviour.
using System;
using System.IO;
using System.Linq;
using System.Collections.Generic;
using System.Text.RegularExpressions;
using UnityEngine;
using UnityEditor;
using UnityEditor.SceneManagement;
using UnityEngine.SceneManagement;
using UnityEngine.Rendering;
using UnityEngine.Rendering.Universal;
using Newtonsoft.Json;
using Newtonsoft.Json.Linq;
public static class ApplyContinuation {
 const string Root="Assets/Afrer_Seconds/";
 static string Repo=>Path.GetFullPath(Path.Combine(Application.dataPath,"../../.."));
 static string ScenePath(string floor)=>Root+"01.Scenes/Stage/Level_"+floor+"_Stealth.unity";
 static Vector3 V(JToken a)=>new Vector3((float)a[0],(float)a[1],(float)a[2]);
 static Vector3 Plan(float u,float h,float v)=>new Vector3(u-24,h,v-16);
 static Dictionary<string,Material> mats=new Dictionary<string,Material>();
 static Transform Child(string name,Transform parent){var g=new GameObject(name);g.transform.SetParent(parent,false);return g.transform;}
 static void Ready(){if(EditorApplication.isPlaying||SceneManager.GetActiveScene().isDirty)throw new Exception("Saved Edit scene required");}
 static void Write(string name,object value)=>File.WriteAllText(Repo+"/Docs/검수/2026-11-06_LevelContinuation/"+name+".json",JsonConvert.SerializeObject(value,Formatting.Indented));
 static void LoadMaterials(){mats.Clear();foreach(string guid in AssetDatabase.FindAssets("LP_ t:Material",new[]{Root+"05.Model/Environment/Common/Materials"})){var m=AssetDatabase.LoadAssetAtPath<Material>(AssetDatabase.GUIDToAssetPath(guid));mats[m.name]=m;}}
 static Material Mapping(string key){
  key=Regex.Replace(key,@"\.\d{3}$","");if(mats.ContainsKey(key))return mats[key];
  if(key.Contains("PipeSteel"))return mats["LP_Pipe"];if(key.Contains("PipeCoupling")||key.Contains("Handrail")||key.Contains("WallTrim"))return mats["LP_Stainless"];
  if(key.Contains("WallSterile")||key.EndsWith("Clinical")||key.EndsWith("Panel"))return mats["LP_WallClean"];
  if(key.Contains("WallConcrete"))return mats["LP_WallConcrete"];if(key.Contains("WallStaff"))return mats["LP_WallStaff"];if(key.Contains("WallSteel")||key.EndsWith("Service"))return mats["LP_WallSteel"];
  if(key.Contains("Plinth"))return mats["LP_Plinth"];if(key.Contains("Teal"))return mats["LP_Teal"];if(key.EndsWith("Light"))return mats["LP_Lamp"];if(key.EndsWith("Floor"))return mats["LP_Floor"];if(key.EndsWith("Ceiling"))return mats["LP_Ceiling"];if(key.EndsWith("Core"))return mats["LP_Core"];if(key.EndsWith("Hazard")||key.EndsWith("Accent"))return mats["LP_SafetyPaint"];if(key.EndsWith("Metal")||key.Contains("PaintedSteel")||key.Contains("Grille"))return mats["LP_Graphite"];
  if(key=="B4_Glass")return AssetDatabase.LoadAssetAtPath<Material>(Root+"05.Model/Environment/B4/Materials/B4_Glass.mat");if(key=="SL_Water")return AssetDatabase.LoadAssetAtPath<Material>(Root+"05.Model/Environment/B5/Materials/SL_Water.mat");throw new Exception("Unmapped material "+key);
 }
 static void Remap(GameObject go){foreach(var r in go.GetComponentsInChildren<Renderer>(true)){r.sharedMaterials=r.sharedMaterials.Select(m=>Mapping(m.name)).ToArray();PrefabUtility.RecordPrefabInstancePropertyModifications(r);}}
 public static object Import(){Ready();var logs=new List<string>();Application.LogCallback cb=(m,s,t)=>{if(t==LogType.Warning||t==LogType.Error||t==LogType.Exception)logs.Add(m);};Application.logMessageReceived+=cb;try{AssetDatabase.Refresh(ImportAssetOptions.ForceSynchronousImport);foreach(string f in new[]{"B5","B4","B3"}){string p=Root+"05.Model/Environment/"+f+"/LC_"+f+"_Architecture.fbx";if(!File.Exists(p))throw new Exception("Model missing: "+p);var im=(ModelImporter)AssetImporter.GetAtPath(p);im.importAnimation=false;im.importLights=false;im.importCameras=false;im.materialImportMode=ModelImporterMaterialImportMode.ImportStandard;im.SaveAndReimport();}}finally{Application.logMessageReceived-=cb;}Write("import",new{logs});return logs;}
 static GameObject Architecture(string floor,Transform parent){var g=(GameObject)PrefabUtility.InstantiatePrefab(AssetDatabase.LoadAssetAtPath<GameObject>(Root+"05.Model/Environment/"+floor+"/LC_"+floor+"_Architecture.fbx"),parent);g.name="Architecture_Sections";Remap(g);return g;}
 static void Collision(JArray data,Transform parent){foreach(var row in data){var g=Child((string)row["name"],parent);g.localPosition=V(row["center"]);g.gameObject.AddComponent<BoxCollider>().size=V(row["size"]);g.gameObject.isStatic=true;}}
 static void Lights(JArray data,Transform parent,bool b3=false){int n=0;foreach(var row in data){var g=Child((string)row["name"]+"_"+n++,parent);g.localPosition=V(row["position"]);g.rotation=Quaternion.LookRotation(V(row["target"])-g.position);var l=g.gameObject.AddComponent<Light>();l.type=LightType.Spot;l.intensity=(float)row["intensity"];l.range=(float)row["range"];l.spotAngle=(float)row["angle"];l.innerSpotAngle=65;l.color=new Color(.88f,.94f,.91f);l.shadows=b3&&n%12==0?LightShadows.Soft:LightShadows.None;}}
 static GameObject Instance(string name,Transform parent,Vector3 p,float yaw){var g=(GameObject)PrefabUtility.InstantiatePrefab(AssetDatabase.LoadAssetAtPath<GameObject>(Root+"05.Model/Props/Common/LP_"+name+".prefab"),parent);g.transform.localPosition=p;g.transform.localRotation=Quaternion.Euler(0,yaw,0);return g;}
 static GameObject Door(string name,Transform parent,Vector3 position,float yaw,bool open){var g=Instance("DoubleSlidingDoor",parent,position,yaw);g.name=name;foreach(string side in new[]{"Left","Right"}){var t=g.transform.Find("Leaf_"+side);t.localPosition=g.transform.Find(side+(open?"_Open":"_Closed")).localPosition;PrefabUtility.RecordPrefabInstancePropertyModifications(t);}foreach(int side in new[]{-1,1}){var k=Instance("Keypad",g.transform,new Vector3(side*.98f,1.35f,side*.20f),side<0?180:0);k.name=side<0?"Keypad_Back":"Keypad_Front";}if(!open)foreach(var r in g.GetComponentsInChildren<Renderer>()){r.sharedMaterials=r.sharedMaterials.Select(m=>m==mats["LP_Indicator"]?mats["LP_Amber"]:m).ToArray();PrefabUtility.RecordPrefabInstancePropertyModifications(r);}return g;}
 static bool WallAt(BoxCollider c,float u){var p=c.transform.position+c.center;return c.name.StartsWith("WallCore")&&Mathf.Abs(p.x-(u-24))<.15f&&p.z>2.001f&&p.z<15.999f;}
 public static object ReloadB5(){if(EditorApplication.isPlaying)throw new Exception("Play mode");EditorSceneManager.OpenScene(ScenePath("B5"));return "Reloaded after unsaved failed external tool";}
 public static object Sections(){Ready();LoadMaterials();var rows=new List<object>();foreach(string floor in new[]{"B5","B4"}){
  var s=EditorSceneManager.OpenScene(ScenePath(floor));var root=s.GetRootGameObjects().Single(g=>g.name.StartsWith(floor+"_Stealth_Level"));if(root.transform.Find("SectionsCollision"))throw new Exception("Sections already applied");var old=root.transform.Find("Architecture_LabPolish");if(!old||old.GetComponentsInChildren<Collider>().Length!=0)throw new Exception("Architecture ownership changed");Architecture(floor,root.transform);UnityEngine.Object.DestroyImmediate(old.gameObject);
  var removed=new List<string>();foreach(var c in (root.transform.Find("StaticCollision")??root.transform.Find("Architecture_Collision")).GetComponentsInChildren<BoxCollider>().Where(c=>WallAt(c,39)||(floor=="B4"&&(WallAt(c,43.5f)||c.name=="Floor_STA"||c.name.Contains("ReviewBoundary")))).ToArray()){removed.Add(c.name);UnityEngine.Object.DestroyImmediate(c.gameObject);}
  var data=JObject.Parse(File.ReadAllText(Repo+"/SourceAssets/LevelContinuation/"+floor+"_sections.json"));Collision((JArray)data["colliders"],Child("SectionsCollision",root.transform));Lights((JArray)data["lights"],Child("LC_StairLighting",root.transform));var portals=Child("TransitionDoors",root.transform);
  if(floor=="B5"){Door("Exit_To_B4_Closed",portals,Plan(39,7.8f,28.25f),90,false);UpperLamp(root);}
  else{
   Door("Exit_To_B3_Closed",portals,Plan(43.5f,6.4f,23.5f),90,false);Door("Return_To_B5_Closed",portals,Plan(39,-7.8f,25),90,false);
   var door=root.transform.Find("Lab_Doors").Cast<Transform>().Single(t=>t.name.EndsWith("_ES_STA"));door.localPosition=Plan(39,0,28.25f);PrefabUtility.RecordPrefabInstancePropertyModifications(door);
   var markers=root.transform.Find("PlanMarkers_NoRuntimeLogic");markers.Find("Entry_StairA").position=Plan(41,0,28.25f);markers.Find("Exit_StairB").position=Plan(46,6.4f,23.5f);
   var player=s.GetRootGameObjects().Single(g=>g.name.StartsWith("Player"));player.transform.position=Plan(41,.89f,28.25f);player.transform.rotation=Quaternion.Euler(0,270,0);PrefabUtility.RecordPrefabInstancePropertyModifications(player.transform);
  }
  var props=root.transform.Find("Lab_Additional_Props");var turns=floor=="B5"?new[]{"Vestibule_ColdSamples","Monitoring_Analyzer"}:new[]{"AN_Analyzer","AS_Analyzer"};foreach(string name in turns){var t=props.Find(name);t.localRotation=Quaternion.Euler(0,floor=="B5"?180:0,0);PrefabUtility.RecordPrefabInstancePropertyModifications(t);foreach(Transform lamp in root.transform.Find("Lab_Task_Lighting"))if(Vector3.Distance(lamp.localPosition,t.localPosition+Vector3.up*2.3f)<.01f){lamp.localRotation=t.localRotation;PrefabUtility.RecordPrefabInstancePropertyModifications(lamp);}}
  EditorSceneManager.MarkSceneDirty(s);EditorSceneManager.SaveScene(s);rows.Add(new{floor,removedOriginalColliders=removed.Count,newColliders=data["colliders"].Count(),newLights=data["lights"].Count(),newPortals=portals.childCount,turnedProps=turns});
 }Write("sections_applied",rows);return rows;}
 static Bounds BoundsOf(GameObject g){var rr=g.GetComponentsInChildren<Renderer>(true);var b=rr[0].bounds;foreach(var r in rr.Skip(1))b.Encapsulate(r.bounds);return b;}
 static void UpperLamp(GameObject root){var fixture=root.transform.Find("Fixture_Details_Blender_Bevelled");foreach(Transform t in fixture)if(t.name.Contains("StairA_LampUpper")){var p=t.position;p.y+=10.8f-t.GetComponent<Renderer>().bounds.center.y;t.position=p;PrefabUtility.RecordPrefabInstancePropertyModifications(t);}foreach(var l in root.transform.Find("Fixture_Lighting").GetComponentsInChildren<Light>())if(l.name=="StairA_Fill"&&l.transform.position.y>9){var p=l.transform.position;p.y=10.65f;l.transform.position=p;}}
 public static object MoveUpperLamp(){Ready();var s=EditorSceneManager.OpenScene(ScenePath("B5"));UpperLamp(s.GetRootGameObjects().Single(g=>g.name.StartsWith("B5_Stealth_Level")));EditorSceneManager.MarkSceneDirty(s);EditorSceneManager.SaveScene(s);return "Upper landing lamp moved above new portal, center y10.8";}
 public static object TuneLighting(){Ready();var s=EditorSceneManager.OpenScene(ScenePath("B3"));var root=s.GetRootGameObjects().Single(g=>g.name.StartsWith("B3_Stealth_Level"));foreach(var l in root.transform.Find("Lighting").GetComponentsInChildren<Light>()){if(l.name.StartsWith("Ceiling_"))l.intensity=l.transform.position.y>4.2f?24:18;else if(l.name.StartsWith("LiftInterior"))l.intensity=14;}EditorSceneManager.MarkSceneDirty(s);EditorSceneManager.SaveScene(s);return "B3 ceiling/local lighting tuned";}
 static void OldProp(string asset,string name,Transform parent,float u,float v,float height,float yaw){var h=Child(name,parent);var g=(GameObject)PrefabUtility.InstantiatePrefab(AssetDatabase.LoadAssetAtPath<GameObject>(Root+"05.Model/"+asset+".prefab"),h);var b=BoundsOf(g);g.transform.localScale*=height/b.size.y;b=BoundsOf(g);g.transform.position-=new Vector3(b.center.x,b.min.y,b.center.z);b=BoundsOf(g);foreach(var c in g.GetComponentsInChildren<Collider>())c.enabled=false;var col=h.gameObject.AddComponent<BoxCollider>();col.center=new Vector3(0,b.size.y/2,0);col.size=b.size*.94f;h.position=Plan(u,0,v);h.rotation=Quaternion.Euler(0,yaw,0);}
 public static object B3(){Ready();LoadMaterials();string path=ScenePath("B3");if(File.Exists(path))throw new Exception("B3 already exists");if(!AssetDatabase.CopyAsset(ScenePath("B4"),path))throw new Exception("Cannot copy scene");var s=EditorSceneManager.OpenScene(path);var original=s.GetRootGameObjects().Single(g=>g.name.StartsWith("B4_Stealth_Level"));var actorSources=original.transform.Find("StaticCharacters");var level=new GameObject("B3_Stealth_Level_V0.01");var actors=Child("StaticCharacters",level.transform);
  var actorSpecs=new[]{new{prefix="G1_",name="G1_North_Visual",u=5.125f,v=2.125f,yaw=90f},new{prefix="G2_",name="G2_South_Visual",u=4.125f,v=25.625f,yaw=90f},new{prefix="G3_",name="G3_Central_Visual",u=20.625f,v=6.125f,yaw=0f},new{prefix="R1_",name="R1_Preparation_Visual",u=13.5f,v=29.5f,yaw=270f},new{prefix="C1_",name="C1_Decontamination",u=34f,v=6f,yaw=250f},new{prefix="C2_",name="C2_EastCorridor",u=37.5f,v=10f,yaw=0f}};
  foreach(var a in actorSpecs){var src=actorSources.Cast<Transform>().Single(t=>t.name.StartsWith(a.prefix));var g=UnityEngine.Object.Instantiate(src.gameObject,actors);g.name=a.name;float y=src.position.y;g.transform.SetPositionAndRotation(Plan(a.u,y,a.v),Quaternion.Euler(0,a.yaw,0));}
  UnityEngine.Object.DestroyImmediate(original);Lightmapping.lightingDataAsset=null;LightmapSettings.lightmaps=new LightmapData[0];RenderSettings.customReflectionTexture=null;Architecture("B3",level.transform);
  var data=JObject.Parse(File.ReadAllText(Repo+"/SourceAssets/B3_StealthLayout/B3_sections.json"));Collision((JArray)data["colliders"],Child("StaticCollision",level.transform));Lights((JArray)data["lights"],Child("Lighting",level.transform),true);
  RenderSettings.ambientMode=AmbientMode.Trilight;RenderSettings.ambientSkyColor=new Color(.42f,.47f,.48f);RenderSettings.ambientEquatorColor=new Color(.28f,.32f,.33f);RenderSettings.ambientGroundColor=new Color(.14f,.17f,.18f);RenderSettings.fog=false;
  var plan=JObject.Parse(File.ReadAllText(Repo+"/Docs/도면/잠입_탐색/layout.json"))["floors"].Single(f=>(string)f["floor"]=="B3");var doors=Child("Lab_Doors",level.transform);int index=0;foreach(var d in plan["doors"])Door("Door_"+(index++).ToString("D2")+"_"+d["a"]+"_"+d["b"],doors,Plan((float)d["x"],0,(float)d["y"]),(string)d["axis"]=="H"?0:90,(string)d["state"]=="open");var td=Child("TransitionDoors",level.transform);Door("Return_To_B4_Closed",td,Plan(46,-6.4f,18),0,false);Door("FreightLift_Entry",td,Plan(43.5f,0,9.2f),0,true);
  var props=Child("Props",level.transform);Action<string,string,float,float,float> put=(type,name,u,v,yaw)=>{var g=Instance(type,props,Plan(u,0,v),yaw);g.name=name;};
  put("SampleColdCabinet","ColdStore_01",1.3f,31.2f,180);put("SampleColdCabinet","ColdStore_02",4.5f,31.2f,180);put("SampleColdCabinet","ColdStore_03",7.7f,31.2f,180);put("BenchAnalyzer","Preparation_Analyzer",16.3f,31.0f,180);put("SampleTrolley","Preparation_Trolley",11.0f,28.3f,90);put("SampleColdCabinet","RackRoom_ColdSamples",17.9f,5.5f,270);put("SampleTrolley","RackRoom_Cart",4.1f,5.2f,90);put("BenchAnalyzer","Clean_Analyzer",34.9f,22.8f,270);put("SampleTrolley","Dirty_SampleCart",23.2f,5.2f,0);put("SampleColdCabinet","Clean_ColdSamples",23.1f,22.8f,90);
  OldProp("Props/Common/P07_SealedWasteBin_B5_Lite","Waste_Bin_01",props,19.2f,31.0f,.95f,180);OldProp("Props/Common/P07_SealedWasteBin_B5_Lite","Waste_Bin_02",props,22.4f,31.0f,.95f,180);OldProp("Props/Common/P07_SealedWasteBin_B5_Lite","Waste_Bin_03",props,25.5f,31.0f,.95f,180);OldProp("Props/Common/P02_WallStorageCabinet_B5_Lite","Staff_Storage",props,28.2f,31,1.8f,180);OldProp("Props/Common/P02_WallStorageCabinet_B5_Lite","Service_Storage",props,40.1f,2,1.8f,90);OldProp("Props/Common/P04_RecordsCabinet_B5_Lite","Specimen_Records",props,17.8f,22.5f,1.8f,270);OldProp("Props/Common/P09_LaboratoryTrolley_B5_Lite","Service_ToolCart",props,46.3f,2,1,270);OldProp("Props/Common/P13_LogisticsTote_B5_Lite","Lift_TransitTote",props,40.4f,15.9f,.9f,0);
  var tone=Child("Lab_Tone",level.transform).gameObject.AddComponent<Volume>();tone.isGlobal=true;tone.priority=20;tone.sharedProfile=AssetDatabase.LoadAssetAtPath<VolumeProfile>(Root+"06.Data/LP_LabTone_B4.asset");var markers=Child("PlanMarkers_NoRuntimeLogic",level.transform);Child("Entry_StairB",markers).position=Plan(46,0,23.5f);Child("Exit_FreightLift",markers).position=Plan(43.5f,0,11);
  var player=s.GetRootGameObjects().Single(g=>g.name.StartsWith("Player"));player.transform.SetPositionAndRotation(Plan(46,.89f,23.5f),Quaternion.Euler(0,270,0));PrefabUtility.RecordPrefabInstancePropertyModifications(player.transform);EditorSceneManager.MarkSceneDirty(s);EditorSceneManager.SaveScene(s);
  var result=new{scene=path,rooms=plan["rooms"].Count(),doors=doors.childCount,transitionDoors=td.childCount,props=props.childCount,actors=actors.childCount,lights=level.GetComponentsInChildren<Light>().Length,colliders=level.GetComponentsInChildren<Collider>().Length};Write("B3_build",result);return result;
 }
